{
  "type_map": {},
  "constraints": [
    {
      "id": "R1",
      "category": "protocol",
      "alternatives": [
        "(df['proto'] == 'tcp') | ((df['swin'] == 0) & (df['dwin'] == 0) & (df['stcpb'] == 0) & (df['dtcpb'] == 0) & (df['tcprtt'] == 0) & (df['synack'] == 0) & (df['ackdat'] == 0))"
      ],
      "features": ["proto", "swin", "dwin", "stcpb", "dtcpb", "tcprtt", "synack", "ackdat"],
      "rationale": "TCP-specific fields must be zero for non-TCP protocols."
    },
    {
      "id": "R2",
      "category": "protocol",
      "alternatives": [
        "(df['is_ftp_login'] == 0) | ((df['proto'] == 'tcp') & (df['service'] == 'ftp'))"
      ],
      "features": ["is_ftp_login", "proto", "service"],
      "rationale": "FTP login indicator requires TCP protocol and FTP service."
    },
    {
      "id": "R3",
      "category": "protocol",
      "alternatives": [
        "((df['trans_depth'] == 0) & (df['response_body_len'] == 0)) | ((df['proto'] == 'tcp') & (df['service'] == 'http'))"
      ],
      "features": ["trans_depth", "response_body_len", "proto", "service"],
      "rationale": "HTTP-specific fields must be zero unless the flow is TCP and HTTP service."
    },
    {
      "id": "R4",
      "category": "protocol",
      "alternatives": [
        "~df['service'].isin(['ftp', 'ftp-data', 'ssh', 'http', 'smtp', 'irc']) | (df['proto'] == 'tcp')"
      ],
      "features": ["service", "proto"],
      "rationale": "These services are TCP-based and must use TCP protocol."
    },
    {
      "id": "R5",
      "category": "protocol",
      "alternatives": [
        "(df['service'] != 'dns') | (df['proto'].isin(['tcp', 'udp']))"
      ],
      "features": ["service", "proto"],
      "rationale": "DNS service can use either TCP or UDP."
    },
    {
      "id": "R6",
      "category": "protocol",
      "alternatives": [
        "(df['proto'] != 'udp') | (~df['state'].isin(['FIN', 'RST']))"
      ],
      "features": ["proto", "state"],
      "rationale": "UDP flows do not have TCP connection termination states FIN or RST."
    }
  ]
}
